        '                p.append(f"modelos.{m[\'id\']}.base no es la revisión fijada en src/humo_kaggle.py.")\n'
        '        for clave in ("adaptador", "adaptador_config", "predicciones_validacion", "registro_validacion"):\n'
        '            if clave in m:\n'
        '                ruta = Path(raiz) / m[clave]["ruta"]\n'
        '                if not ruta.is_file():\n'
        '                    p.append(f"modelos.{m[\'id\']}.{clave}: no existe el archivo local.")\n'
        '                elif sha256_archivo(ruta) != m[clave]["sha256"]:\n'
        '                    p.append(f"modelos.{m[\'id\']}.{clave}: el SHA-256 no es el del archivo local.")\n'
        '        if "adaptador" in m:\n'
        '            res = json.loads((Path(raiz) / m["resultado_validacion"]).read_text(encoding="utf-8"))\n'
        '            if m["adaptador"]["sha256"] != res["modelo"].get("adaptador_sha256"):\n'
        '                p.append(f"modelos.{m[\'id\']}.adaptador.sha256 no es el de su resultado de validación.")\n'
        '\n'
        '    p.extend(problemas_reproduccion(config))\n'
        '\n'
        '    fuera_de_test = {x["modelo"] for x in config["no_van_a_test"]}\n'
        '    if len(config["no_van_a_test"]) != 7 or len(fuera_de_test) != 7 or fuera_de_test & set(modelos):\n'
        '        p.append("no_van_a_test debe listar 7 modelos distintos, ninguno de los 8 que van a test.")\n'
        '    comp = config["comparaciones"]\n'
        '    for grupo, g in comp.items():\n'
        '        if not isinstance(g, Mapping) or "pares" not in g:\n'
        '            continue\n'
        '        if not isinstance(g["pares"], list) or not g["pares"]:\n'
        '            p.append(f"comparaciones.{grupo}.pares debe ser una lista no vacía.")\n'
        '            continue\n'
        '        for par in g["pares"]:\n'
        '            if isinstance(par, str):  # clave de otro grupo cuyos pares se reutilizan (hard)\n'
