        '                    p.append(f"comparaciones.{grupo}: \'{par}\' no es un grupo de comparaciones con pares explícitos.")\n'
        '            elif not isinstance(par, Mapping) or par.get("a") not in modelos or par.get("b") not in modelos or par["a"] == par["b"]:\n'
        '                p.append(f"comparaciones.{grupo}: un par no nombra dos modelos distintos del config.")\n'
        '    if "secundarias_sector" in comp:\n'
