        '            p.append("comparaciones.secundarias_sector.pares no son los pares de principales y secundarias, en ese orden.")\n'
        '\n'
        '    commit = config["registro"]["commit_codigo"]\n'
        '    if commit != "pendiente":\n'
        '        if not RE_COMMIT.fullmatch(commit):\n'
        '            p.append("registro.commit_codigo no es un commit de 40 hexadecimales.")\n'
