        '    "sha256_de_este_archivo": "Cada script de la Fase 4 (kernel, baselines y evaluación final) registra en su salida el SHA-256 de este archivo.",\n'
        '    "hard_set": "No se usa para elegir modelos ni hiperparámetros, y se evalúa una sola vez, junto con test."\n'
